exercise.solution:
def parse_ticket(raw: str) -> Ticket:
    text = raw.strip()
    if text.startswith("```"):
        text = text.split("\n", 1)[1].rsplit("```", 1)[0]
    try:
        return Ticket.model_validate_json(text)
    except ValidationError as err:
        raise ValueError(f"invalid ticket: {err}") from err
